contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 unused) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(unused == 0);
        require(address(this).balance >= 0);

        uint beforeUser = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint beforeContract = address(c).balance;

        bool reverted;
        c.withdrawBalance(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint afterUser = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint afterContract = address(c).balance;

        assert(beforeUser == 0 && !reverted && afterUser == 0 && afterContract == beforeContract);
    }

    receive() external payable {}
}

